     ) AS b 
WHERE b.RowNum = 1;

DELETE r WITH (ROWLOCK)
FROM dbo.CustomerClassification_ResetBalance AS r 
	LEFT JOIN #tmpResetBlance AS tmp ON tmp.CustId = r.CustId
WHERE tmp.CustId IS NULL;

UPDATE r WITH(ROWLOCK, UPDLOCK)
SET r.ResetDate = tmp.ResetDate,
	r.CreatedTime = tmp.CreatedTime
FROM dbo.CustomerClassification_ResetBalance AS r
		INNER JOIN #tmpResetBlance AS tmp ON tmp.CustId = r.CustId

DROP TABLE	#tmpResetBlance;